let result = async {
    // 查身份、授权、检查实际文件以及整批提交共享同一正式租约。
    let lease = self.files.payload_lease().await;
    let (ids, paths) = normalize(args)?;
    let mut delivered = Vec::new();
    for id in ids {
        let file = self
            .files
            .get_file(ctx.session_id.as_str(), &id)
            .await
            .map_err(|e| e.to_string())?
            .ok_or_else(|| format!("SessionFile not found: {id}"))?;
        if file.status != "available" || !Path::new(&file.real_path).exists() {
            return Err(format!("SessionFile payload missing: {id}"));
        }
        delivered.push(file);
    }
    for path in paths {
        let scope = self
            .access
            .authorize(
                ctx.principal.storage_kind(),
                &ctx.principal.storage_subject(),
                ctx.session_id.as_str(),
                Path::new(&path),
                &self.cwd,
                ResourceOp::Read,
            )
            .map_err(|e| e.to_string())?;

async fn register_file_inner(
    &self,
    session_id: &str,
    real_path: &Path,
    source_key: Option<&str>,
    label: Option<&str>,
    origin: &str,
) -> Result<SessionFileView, SessionFileError> {
    let now = self.now_ms();
    store::record_current_activity(&self.db, session_id, now).await?;
    let canonical = std::fs::canonicalize(real_path).map_err(|_| {
        SessionFileError::Io(std::io::Error::new(
            std::io::ErrorKind::NotFound,
            format!("file not found: {}", real_path.display()),
        ))

/// 运行期的真实活动单调前进；历史导入的原 upsert 接口保留显式历史时刻。
pub async fn record_current_activity(
    db: &RunDatabase,
    session_id: &str,
    now: u64,
) -> Result<(), StorageError> {
    let sid = session_id.to_string();
    db.queue().submit(move|conn|{
        conn.execute("INSERT INTO sessions (session_id,agent_id,owner_user_id,title,created_at_unix_ms,last_activity_unix_ms) VALUES (?1,'agent','user_local','',?2,?2) ON CONFLICT(session_id) DO UPDATE SET last_activity_unix_ms=MAX(COALESCE(sessions.last_activity_unix_ms,0),?2)",rusqlite::params![sid,now as i64]).map_err(map_err)?;Ok(())
    }).await
}

